{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Aromatherapy Care</title>
  <meta name='description' content='Gentle, safety-first aromatherapy consultations and blends in {{CITY}}, {{STATE}}.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
</head>
<body class='theme-glass'>
  <header class='site-header'>
    <div class='brand'>
      <div class='logo'>
        <svg width='48' height='48' viewBox='0 0 48 48' aria-hidden='true'>
          <defs>
            <linearGradient id='g1' x1='0' x2='1'>
              <stop offset='0' stop-color='#C6FFD3' />
              <stop offset='1' stop-color='#DCEBFF' />
            </linearGradient>
          </defs>
          <rect width='48' height='48' rx='10' fill='url(#g1)' />
          <g transform='translate(8 8)' fill='none' stroke='#0A2' stroke-width='2'>
            <path d='M6 18c4-8 10-8 14 0' stroke-linecap='round' />
            <circle cx='6' cy='6' r='3' fill='#fff' opacity='0.08'/>
            <circle cx='18' cy='6' r='3' fill='#fff' opacity='0.08'/>
          </g>
        </svg>
      </div>
      <div class='identity'>
        <strong class='name'>{{BUSINESS_NAME}}</strong>
        <small class='tag'>{{TAGLINE}}</small>
      </div>
    </div>
    <nav class='nav' aria-label='Primary'>
      <button class='nav-toggle' id='navToggle' aria-expanded='false' aria-controls='navList'>Menu</button>
      <ul id='navList' class='nav-list'>
        <li><a href='services.html'>Offerings</a></li>
        <li><a href='blends.html'>Blends & Notes</a></li>
        <li><a href='shop.html'>Small Shop</a></li>
        <li><a href='pricing.html'>Plans</a></li>
        <li><a href='about.html'>About the Practice</a></li>
        <li><a href='book.html'>Book a Session</a></li>
        <li><a href='contact.html' class='accent'>Contact</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- Hero (safety-forward, calm clinical tone) -->
    <section class='hero' style="background-image: url('assets/img/pattern.svg');">
      <div class='hero-inner glass'>
        <h1>Careful aromatherapy that listens first</h1>
        <p class='lead'>We blend thoughtfully and prioritize safety — personalized sessions and home blends for everyday calm in {{CITY}}.</p>
        <div class='hero-ctas'>
          <a href='{{PRIMARY_CTA_URL}}' class='btn primary'>{{PRIMARY_CTA_LABEL}}</a>
          <a href='about.html' class='btn ghost'>Meet {{PRACTITIONER_NAME}}</a>
        </div>
        <p class='micro'>Phone: <a href='tel:{{PHONE}}'>{{PHONE}}</a> • Email: <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></p>
      </div>
    </section>

    <!-- Social proof (testimonials) -->
    <section class='social-proof glass-section'>
      <div class='wrap'>
        <h2>Kind words from clients</h2>
        <div class='testimonials'>
          <blockquote>
            "Compassionate, clear, and safety-minded. I felt heard and left with tools I could use at home."<cite>— A client in {{CITY}}</cite>
          </blockquote>
          <blockquote>
            "The blends are subtle and effective. I appreciated the dilution guidance and instructions for pets."<cite>— Local practitioner</cite>
          </blockquote>
        </div>
      </div>
    </section>

    <!-- Benefits (structured, clinical calm) -->
    <section class='benefits glass-section' aria-labelledby='benefitsTitle'>
      <div class='wrap'>
        <h2 id='benefitsTitle'>What clients gain</h2>
        <ul class='benefit-grid'>
          <li>
            <h3>Personalized plans</h3>
            <p>We assess preferences, sensitivities, and environment to recommend blends and delivery methods suited to you.</p>
          </li>
          <li>
            <h3>Safety-forward practice</h3>
            <p>Detailed dilution ratios, patch-test instructions, and guidance for vulnerable groups are provided with every session.</p>
          </li>
          <li>
            <h3>Practical at-home care</h3>
            <p>Diffuser protocols, roller recipes, and storage tips so blends are effective and stable at home.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- Process (clear step-by-step) -->
    <section class='process glass-section' aria-labelledby='processTitle'>
      <div class='wrap'>
        <h2 id='processTitle'>How a typical consultation works</h2>
        <ol class='process-list'>
          <li><strong>1. Pre-consult form</strong> — Share history, preferences, and any contraindications before the session.</li>
          <li><strong>2. Guided session</strong> — Discussion, scent sampling, and formulation with safety checks.</li>
          <li><strong>3. Blends & instructions</strong> — Receive labeled blends, dilution guidance, and written protocols to keep at home.</li>
          <li><strong>4. Follow-up</strong> — Optional check-in to adjust blends and ensure tolerability.</li>
        </ol>
      </div>
    </section>

    <!-- FAQ (must include dilution, patch test, pets, pregnancy) -->
    <section class='faq glass-section' aria-labelledby='faqTitle'>
      <div class='wrap'>
        <h2 id='faqTitle'>Frequently asked, answered with care</h2>
        <div class='qa'>
          <h3>What dilution should I use?</h3>
          <p>Recommended dilutions vary by application and age. Typical roller dilutions for adults are 2–5% essential oils in a carrier. We include exact ratios for each blend and purpose, and we never recommend undiluted application to skin.</p>
        </div>
        <div class='qa'>
          <h3>How do I perform a patch test?</h3>
          <p>Apply a small amount of a diluted blend to an inner forearm and observe for 24 hours. If irritation occurs, discontinue use and consult the practitioner. Patch tests are part of every new topical recommendation.</p>
        </div>
        <div class='qa'>
          <h3>Are essential oils safe for pets?</h3>
          <p>Some oils can be harmful to animals. We provide explicit pet-safety guidance and alternative blends when animals are present. Never apply essential oils directly to a pet without veterinary approval.</p>
        </div>
        <div class='qa'>
          <h3>Can I use oils during pregnancy?</h3>
          <p>Pregnancy requires special consideration. We use conservative, evidence-aware guidance and will avoid or modify recommendations for pregnant or breastfeeding clients. Always consult your healthcare provider alongside our guidance.</p>
        </div>
      </div>
    </section>

    <!-- Lead magnet (email capture) -->
    <section class='lead-magnet glass-section' aria-labelledby='leadTitle'>
      <div class='wrap'>
        <h2 id='leadTitle'>Free guide: Safe Home Aromatherapy</h2>
        <p>Sign up to receive a concise guide with dilution charts, a quick patch-test checklist, and two gentle at-home blends.</p>
        <form id='leadForm' class='lead-form' aria-label='Download guide form'>
          <label for='leadEmail' class='visually-hidden'>Email</label>
          <input id='leadEmail' type='email' name='email' placeholder='Email address' required>
          <button type='submit' class='btn primary'>Send the guide</button>
        </form>
        <p class='micro'>We respect privacy. Your email is stored only to deliver the guide and occasional practice updates.</p>
      </div>
    </section>

    <!-- Call to action -->
    <section class='cta glass-section'>
      <div class='wrap'>
        <h2>Ready to explore a safe blend?</h2>
        <p>Book a consultation for an individualized plan. Remote and in-person options available.</p>
        <a href='book.html' class='btn primary large'>Book with {{PRACTITIONER_NAME}}</a>
      </div>
    </section>

  </main>

  <footer class='site-footer glass'>
    <div class='wrap'>
      <p>&copy; <span id='year'></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}. All care is individualized; not a substitute for medical advice.</p>
      <nav class='foot-nav' aria-label='Footer'>
        <a href='privacy.html'>Privacy</a>
        <a href='contact.html'>Contact</a>
        <a href='sitemap.xml'>Sitemap</a>
      </nav>
    </div>
  </footer>

<script src='assets/js/main.js' defer></script>
</body>
</html>"} 
