{"path":"assets/css/styles.css","content":":root{
  --bg:#0b1020;
  --glass-bg:rgba(255,255,255,0.06);
  --glass-border:rgba(255,255,255,0.08);
  --accent:#6bd4a5;
  --accent-2:#9bd1ff;
  --muted:#cfe7ff;
  --radius:14px;
  --fw-regular:400;
  --fw-strong:600;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--muted);background:linear-gradient(180deg,#071025 0%,#08192a 60%);background-attachment:fixed;}
.theme-glass{background-image:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.02));}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;backdrop-filter:blur(6px);}
.brand{display:flex;gap:12px;align-items:center}
.identity .name{display:block;font-weight:700;color:var(--accent-2)}
.identity .tag{font-size:13px;color:#bcd7ff}
.nav{position:relative}
.nav-toggle{display:none;background:none;border:1px solid var(--glass-border);padding:8px 12px;border-radius:8px;color:var(--muted)}
.nav-list{display:flex;gap:14px;list-style:none;margin:0;padding:0}
.nav-list a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.nav-list a.accent{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#072}
.hero{padding:60px 20px;background-repeat:no-repeat;background-size:cover}
.hero-inner{max-width:980px;margin:0 auto;padding:36px;border-radius:var(--radius);background:var(--glass-bg);border:1px solid var(--glass-border);backdrop-filter:blur(8px)}
.hero h1{margin:0 0 8px;font-size:28px;color:#e8fbf1}
.hero .lead{color:#d7eef8;margin:0 0 18px}
.hero-ctas{display:flex;gap:12px;margin-bottom:10px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#052}
.btn.ghost{background:transparent;border:1px solid var(--glass-border);color:var(--muted)}
.btn.large{padding:14px 20px;font-size:16px}
.micro{font-size:13px;color:#bcd7ff}
.glass-section{padding:36px 20px}
.wrap{max-width:1100px;margin:0 auto}
.social-proof .testimonials{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}
blockquote{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:16px;border-radius:12px;border:1px solid var(--glass-border);margin:0}
blockquote cite{display:block;margin-top:8px;color:#bcd7ff;font-size:13px}
.benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;list-style:none;padding:0;margin:14px 0 0}
.benefit-grid li{background:var(--glass-bg);padding:16px;border-radius:12px;border:1px solid var(--glass-border)}
.process-list{counter-reset:steps;margin:14px 0 0;padding-left:0}
.process-list li{list-style:none;padding:12px 0;border-bottom:1px dashed rgba(255,255,255,0.03)}
.process-list li strong{display:block;margin-bottom:6px}
.faq .qa{margin-bottom:12px}
.lead-form{display:flex;gap:8px;margin-top:12px}
.lead-form input[type='email']{flex:1;padding:10px;border-radius:10px;border:1px solid var(--glass-border);background:rgba(255,255,255,0.02);color:var(--muted)}
.site-footer{padding:18px 28px;margin-top:28px}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.foot-nav a{color:#bcd7ff;margin-left:12px;text-decoration:none}
.visually-hidden{position:absolute!important;height:1px;width:1px;overflow:hidden;clip:rect(1px,1px,1px,1px);white-space:nowrap}
/* Responsive */
@media(max-width:900px){
  .nav-list{display:none;position:absolute;right:10px;top:52px;background:var(--glass-bg);padding:12px;border-radius:12px;border:1px solid var(--glass-border);flex-direction:column}
  .nav-toggle{display:inline-block}
  .social-proof .testimonials{grid-template-columns:1fr}
  .benefit-grid{grid-template-columns:1fr}
}
/* Decorative: use SVG pattern as subtle overlay */
.hero::after{content:'';position:absolute;left:0;right:0;top:0;bottom:0;opacity:0.06;pointer-events:none;background-image:url('../assets/img/pattern.svg');background-repeat:repeat}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Year in footer
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Mobile nav toggle
  var navToggle=document.getElementById('navToggle');
  var navList=document.getElementById('navList');
  if(navToggle&&navList){
    navToggle.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded', String(!expanded));
      if(navList.style.display==='flex') navList.style.display=''; else navList.style.display='flex';
    });
  }

  // Lead magnet form handling (no external calls) -- simulate download
  var leadForm=document.getElementById('leadForm');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email=leadForm.querySelector('input[type="email"]').value.trim();
      if(!email||!email.includes('@')){
        alert('Please enter a valid email to receive the guide.');
        return;
      }
      try{localStorage.setItem('lead_email',email);}catch(e){}
      // create a small downloadable blob as the guide
      var content='Safe Home Aromatherapy\n\n- Dilution chart (2-5% typical for adults)\n- Patch-test checklist\n- Two gentle roller blends\n\nFor personalized guidance, book a consultation.';
      var blob=new Blob([content],{type:'text/plain'});
      var url=URL.createObjectURL(blob);
      var a=document.createElement('a'); a.href=url; a.download='safe-home-aromatherapy.txt'; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function(){URL.revokeObjectURL(url);},3000);
      alert('Guide downloaded. We also sent a confirmation to ' + email + ' (simulated).');
      leadForm.reset();
    });
  }

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var target=document.querySelector(this.getAttribute('href'));
      if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth'});}    
    });
  });
});"} 
